function solve(input) {
  const { nodes, edges } = input;
  const nodeSet = new Set(nodes);
  const adj = new Map();
  const inDegree = new Map();

  for (const n of nodes) {
    adj.set(n, new Set());
    inDegree.set(n, 0);
  }

  for (const [u, v] of edges) {
    if (u === v) return null;
    if (!adj.get(u).has(v)) {
      adj.get(u).add(v);
      inDegree.set(v, inDegree.get(v) + 1);
    }
  }

  // Min-heap
  const heap = [];
  function push(x) { heap.push(x); let i = heap.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (heap[p] <= heap[i]) break; [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } }
  function pop() { const top = heap[0]; const last = heap.pop(); if (heap.length) { heap[0] = last; let i = 0; while (true) { let c = 2 * i + 1; if (c >= heap.length) break; if (c + 1 < heap.length && heap[c + 1] < heap[c]) c++; if (heap[i] <= heap[c]) break; [heap[i], heap[c]] = [heap[c], heap[i]]; i = c; } } return top; }
  function empty() { return heap.length === 0; }

  for (const n of nodes) {
    if (inDegree.get(n) === 0) push(n);
  }

  const result = [];
  while (!empty()) {
    const u = pop();
    result.push(u);
    for (const v of adj.get(u)) {
      inDegree.set(v, inDegree.get(v) - 1);
      if (inDegree.get(v) === 0) push(v);
    }
  }

  return result.length === nodes.length ? result : null;
}
